map "https://fhir-sid.stage.opensrp.id/fhir/StructureMap/unicef-mexico-lactating-outcome" = "Close Lactating"

uses "http://hl7.org/fhir/StructureDefinition/QuestionnaireReponse" as source
uses "http://hl7.org/fhir/StructureDefinition/Bundle" as target

group lactOutRegistration(source src : QuestionnaireResponse, target bundle: Bundle) {
    src -> bundle.type = "collection" "r_bundle_type";
    src -> evaluate(src, $this.subject) as refPatient
     then extractLactOutEncounter(src, bundle, refPatient) "r_bundle_entries";
}

group extractLactOutEncounter(source src : QuestionnaireResponse, target bundle: Bundle, source refPatient: Patient,) {
    src -> bundle.entry as entry, entry.resource = create('Encounter') as encounter then {
        src -> encounter.id = uuid() "r_en_id";
        src -> encounter.status = 'finished' "r_en_st";
        src -> encounter.class = c("http://terminology.hl7.org/CodeSystem/v3-ActCode", "HH", "Home Health") "r_en_cls";
        src -> encounter.type = create('CodeableConcept') as concept then {
            src -> concept.coding = c("http://snomed.info/sct", "234234234") as coding then {
                src -> coding.display = 'Lactating routine Visit' "r_en_cod_disp";
            } "r_en_cc_cod";
            src -> concept.text = 'Lactating Visit' "r_en_typ_text";
        } "r_en_typ";
        src -> encounter.priority = create('CodeableConcept') as concept then {
            src -> concept.coding = c("http://snomed.info/sct", "17621005") as coding then {
                src -> coding.display = 'Normal' "r_en_cod_disp";
            } "r_en_cc_cod";
            src -> concept.text = 'Normal' "r_en_prio_text";
        } "r_en_prio";
    	src -> encounter.subject = evaluate(src, $this.subject) "r_en_sub";
        // src -> encounter.participant = automatically set by code in questionnaire view model
        src -> encounter.period = create('Period') as enPeriod then {
            src -> enPeriod.start = evaluate(src, now()) "r_en_per_start";
            src -> enPeriod.end = evaluate(src, now()) "r_en_per_end";
        } "r_en_per";
        src -> encounter.reasonCode = create('CodeableConcept') as concept then {
            src -> concept.coding = c("http://smartregsiter.org/", "lactating_visit") as coding then {
                src -> coding.display = 'Lactating routine Visit' "r_en_rc_cod_disp";
            } "r_en_rc_cod";
            src -> concept.text = 'Lactating routine Visit' "r_en_text";
        } "r_en_reason";
        src then updatePNCCondition(src, bundle, refPatient) "r_update_preganncy";
    } "r_en";
}

/* Update Existing lactating Condition*/
group updatePNCCondition(source src : QuestionnaireResponse, target bundle : Bundle, source refPatient : Reference) {
    src.item as item where(linkId = "lactatingConditionId" and answer.value.exists()) then {
          src->bundle.entry as entry,
          entry.resource = create("Condition") as cnd then {
              src->cnd.id = create("id") as cnd_id then {
                  src->cnd_id.value = evaluate(item, $this.answer.value) "r_item_cnd_id_value";
              } "r_item_cnd_id";
              src -> cnd.clinicalStatus = cc("http://terminology.hl7.org/CodeSystem/condition-clinical", "inactive") "r_cnd_clinical_status";
              //TODO update close date for conditions - This seems to be a dedution between Encounter record dat and Condtion onset
          } "r_cnd";
      } "r_item";
}